# Builds wv-truck-parking-dashboard.html from wv-truck-parking-master.csv.
# Interactive dashboard: Leaflet map (streets + Esri satellite), facility list,
# filters, live charts, per-facility detail modal with local satellite imagery
# and a TruckStopsAndServices.com source tab (from wv-truck-parking-tss.csv,
# generated by tools\fetch-tss.ps1), printable report generation, and filtered
# CSV export.
# Rerun after any master CSV or TSS CSV edit:
#   powershell -ExecutionPolicy Bypass -File tools\build-dashboard.ps1
# Requires internet in the browser for map tiles + Leaflet CDN; everything else is local.

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$csvPath = Join-Path $root 'wv-truck-parking-master.csv'
$outPath = Join-Path $root 'wv-truck-parking-dashboard.html'
$rows = Import-Csv $csvPath

# capacity table + classification helpers shared with build-summary-pdf.ps1
. (Join-Path $PSScriptRoot 'facility-classify.ps1')

# toll facility + traffic layer manifest/loader (see tools\traffic-data.ps1)
. (Join-Path $PSScriptRoot 'traffic-data.ps1')

# truckstopsandservices.com source data (see tools\fetch-tss.ps1); optional
$tssPath = Join-Path $root 'wv-truck-parking-tss.csv'
$tssByName = @{}
$tssDate = ''
if (Test-Path $tssPath) {
  foreach ($t in Import-Csv $tssPath) {
    $tssByName[$t.MasterName] = $t
    if ($t.FetchedDate -gt $tssDate) { $tssDate = $t.FetchedDate }
  }
}

# Parking Study locations (included_locations.txt IDs -> master names, see
# tools\study-map.csv); drives the "Show Parking Study Locations only" toggle.
$studyByName = @{}
$studyMapPath = Join-Path $PSScriptRoot 'study-map.csv'
if (Test-Path $studyMapPath) {
  $masterNames = @{}
  foreach ($r in $rows) { $masterNames[$r.Name] = $true }
  foreach ($s in Import-Csv $studyMapPath) {
    if (-not $masterNames.ContainsKey($s.MasterName)) {
      Write-Warning "study-map.csv: $($s.StudyId) '$($s.MasterName)' has no matching master CSV row"
      continue
    }
    if ($studyByName.ContainsKey($s.MasterName)) { $studyByName[$s.MasterName] += ", $($s.StudyId)" }
    else { $studyByName[$s.MasterName] = $s.StudyId }
  }
}

# satellite spot counts per study location (tools\satcount\summarize.py);
# optional -- the tab shows "not available" if the summary is missing.
$satcByName = @{}
$satcPath = Join-Path $root 'satellite-count\study-summary.csv'
if (Test-Path $satcPath) {
  foreach ($c in Import-Csv $satcPath) {
    $o = [ordered]@{}
    foreach ($p in $c.PSObject.Properties) { $o[$p.Name] = $p.Value }
    $ov = "satellite-count\overlays\$($c.site_id).jpg"
    $o['overlay'] = $(if ($c.site_id -and (Test-Path (Join-Path $root $ov))) { "satellite-count/overlays/$($c.site_id).jpg" } else { '' })
    # exact Esri World Imagery export the count image was fetched with (sidecar written by tools\satcount\esri.py)
    $o['image_url'] = ''
    $side = Join-Path $root "satellite-count\images\$($c.site_id).png.json"
    if ($c.site_id -and (Test-Path $side)) {
      $j = Get-Content $side -Raw | ConvertFrom-Json
      $bb = ($j.bbox_3857 | ForEach-Object { [string]::Format([Globalization.CultureInfo]::InvariantCulture, '{0:R}', [double]$_) }) -join ','
      $o['image_url'] = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/export?bbox=$bb&bboxSR=3857&imageSR=3857&size=$($j.size_px[0]),$($j.size_px[1])&format=png&f=image"
      # report crop: bounding box of the digitized lot outlines + rows (base-image pixels), padded,
      # as fractions of the image so the report can zoom the overlay onto the counted lot
      $dig = Join-Path $root "satellite-count\digitizing\$($c.site_id).json"
      if (Test-Path $dig) {
        $d = Get-Content $dig -Raw | ConvertFrom-Json
        $xs = @(); $ys = @()
        foreach ($l in @($d.lots)) { foreach ($pt in @($l.polygon)) { $xs += [double]$pt[0]; $ys += [double]$pt[1] } }
        foreach ($rw in @($d.rows)) { foreach ($pt in @($rw.p0, $rw.p1)) { if ($pt) { $xs += [double]$pt[0]; $ys += [double]$pt[1] } } }
        if ($xs.Count) {
          $W = [double]$j.size_px[0]; $H = [double]$j.size_px[1]
          $x0 = ($xs | Measure-Object -Minimum).Minimum; $x1 = ($xs | Measure-Object -Maximum).Maximum
          $y0 = ($ys | Measure-Object -Minimum).Minimum; $y1 = ($ys | Measure-Object -Maximum).Maximum
          $pad = [Math]::Max(60, 0.15 * [Math]::Max($x1 - $x0, $y1 - $y0))
          $o['crop'] = @(
            [Math]::Round([Math]::Max(0, $x0 - $pad) / $W, 4), [Math]::Round([Math]::Max(0, $y0 - $pad) / $H, 4),
            [Math]::Round([Math]::Min($W, $x1 + $pad) / $W, 4), [Math]::Round([Math]::Min($H, $y1 + $pad) / $H, 4),
            $W, $H)
        }
      }
    }
    $satcByName[$c.location] = $o
  }
}

$headers = $rows[0].psobject.Properties.Name
$i = 0
$list = foreach ($r in $rows) {
  $e = $cap[$r.Name]
  if ($null -eq $e) { throw "No capacity entry for: $($r.Name)" }
  $lat = $null; $lon = $null
  if ($r.Latitude -match '\d') { $lat = [double]$r.Latitude }
  if ($r.Longitude -match '\d') { $lon = [double]$r.Longitude }
  $sat = $r.'Satellite image'
  if ($sat -and -not (Test-Path (Join-Path $root "satellite\$sat"))) { $sat = '' }
  $raw = [ordered]@{}
  foreach ($h in $headers) { $raw[$h] = $r.$h }
  [pscustomobject]@{
    id = $i; name = $r.Name
    corr = Get-CorridorGroup $r.Corridor
    type = Get-TypeGroup $r.'Facility type'
    own = Get-OwnerShort $r.Ownership
    status = Get-StatusShort $r.Status
    conf = $r.Confidence
    lat = $lat; lon = $lon
    capMid = $e.mid; capClass = $e.class
    sat = $sat
    studyId = $(if ($studyByName.ContainsKey($r.Name)) { $studyByName[$r.Name] } else { '' })
    satc = $(if ($satcByName.ContainsKey($r.Name)) { $satcByName[$r.Name] } else { $null })
    raw = $raw
    caps = $(if ($capSources.ContainsKey($r.Name)) { @($capSources[$r.Name]) } else { @() })
    capAgree = $(Get-CapAgreement $(if ($capSources.ContainsKey($r.Name)) { $capSources[$r.Name] } else { @() }))
    tss = $(if ($tssByName.ContainsKey($r.Name)) {
      $t = $tssByName[$r.Name]
      $o = [ordered]@{}
      foreach ($p in $t.PSObject.Properties) { if ($p.Name -ne 'MasterName') { $o[$p.Name] = $p.Value } }
      $o
    } else { $null })
  }
  $i++
}
$json = ConvertTo-Json -InputObject @($list) -Depth 6 -Compress
$colsJson = ConvertTo-Json -InputObject @($headers) -Compress
$today = Get-Date -Format 'MMMM d, yyyy'

# toll + traffic data layers (see tools\traffic-data.ps1); each layer's
# hasData flag is computed from actual traffic-data\*.csv row counts.
$traffic = Get-TrafficLayers -Root $root
$trafficJson = ConvertTo-Json -InputObject $traffic.Layers -Depth 6 -Compress
$trafficMetaJson = ConvertTo-Json -InputObject @($traffic.Meta) -Depth 4 -Compress
$trafficLibJs = Get-Content (Join-Path $PSScriptRoot 'traffic-lib.js') -Raw

$tpl = @'
<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>WV Truck Parking Dashboard</title>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css">
<link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css">
<script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script>
<style>
:root {
  --bg:#f9f9f7; --surface:#fcfcfb; --ink:#0b0b0b; --ink2:#52514e; --muted:#898781;
  --grid:#e1e0d9; --border:rgba(11,11,11,.10); --accent:#2a78d6; --accent-ink:#fff;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg:#0d0d0d; --surface:#1a1a19; --ink:#ffffff; --ink2:#c3c2b7; --muted:#898781;
    --grid:#2c2c2a; --border:rgba(255,255,255,.10); --accent:#3987e5;
  }
}
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--ink); font-family:system-ui,-apple-system,"Segoe UI",sans-serif; font-size:14px; line-height:1.45; }
.app { max-width:1500px; margin:0 auto; padding:14px 18px 30px; }
.card { background:var(--surface); border:1px solid var(--border); border-radius:10px; }

header.topbar { display:flex; flex-wrap:wrap; align-items:flex-end; gap:12px; margin-bottom:12px; }
.topbar h1 { font-size:21px; margin:0; letter-spacing:-.2px; }
.topbar .sub { color:var(--ink2); font-size:12.5px; }
.topbar .actions { margin-left:auto; display:flex; gap:8px; }
button, select, input[type=text] { font:inherit; font-size:13px; color:var(--ink); background:var(--surface); border:1px solid var(--border); border-radius:7px; padding:6px 10px; }
button { cursor:pointer; }
button.primary { background:var(--accent); color:var(--accent-ink); border-color:var(--accent); font-weight:600; }
button:hover { filter:brightness(1.05); }

.kpis { display:grid; grid-template-columns:repeat(5,1fr); gap:10px; margin-bottom:12px; }
.kpi { padding:10px 14px; }
.kpi .v { font-size:24px; font-weight:700; line-height:1.1; }
.kpi .l { font-size:11px; color:var(--ink2); text-transform:uppercase; letter-spacing:.4px; margin-top:2px; }

.filters { display:flex; flex-wrap:wrap; gap:8px; align-items:center; padding:10px 12px; margin-bottom:12px; }
.filters input[type=text] { width:210px; }
.filters .spacer { margin-left:auto; color:var(--ink2); font-size:12.5px; }
.dd { position:relative; }
.dd > button { display:flex; gap:6px; align-items:center; }
.dd > button .n { background:var(--accent); color:#fff; border-radius:10px; font-size:10.5px; padding:0 6px; line-height:16px; }
.dd-panel { position:absolute; top:calc(100% + 4px); left:0; z-index:1500; background:var(--surface); border:1px solid var(--border); border-radius:8px; box-shadow:0 6px 24px rgba(0,0,0,.22); padding:8px 12px; min-width:250px; max-height:320px; overflow-y:auto; display:none; }
.dd.open .dd-panel { display:block; }
.dd-panel label { display:flex; gap:7px; align-items:flex-start; font-size:12.5px; padding:3px 0; cursor:pointer; }
.dd-panel .dd-clear { font-size:11.5px; color:var(--accent); cursor:pointer; margin-bottom:4px; display:inline-block; }
.dd-panel .hrow { display:flex; justify-content:space-between; align-items:baseline; gap:14px; font-size:12.5px; padding:3px 0; }
.dd-panel .hrow a { color:var(--accent); white-space:nowrap; font-size:11.5px; }
.fcard { position:relative; }
.fcard .nm { padding-right:62px; }
.fcard .hidebtn { position:absolute; top:7px; right:8px; font-size:11px; color:var(--muted); border:1px solid var(--border); border-radius:6px; padding:1px 7px; background:var(--bg); cursor:pointer; }
.fcard .hidebtn:hover { color:var(--accent); border-color:var(--accent); }
.estbox, .vbox { background:var(--bg); border:1px solid var(--border); border-radius:8px; padding:8px 10px; font-size:12.5px; margin:8px 0 0; }
.estbox span { color:var(--ink2); }
.vbox.ok { border-color:#00830066; color:#006300; }
.capag { border-radius:8px; padding:7px 10px; font-size:12.5px; margin:8px 0 6px; border:1px solid var(--border); background:var(--bg); }
.capag.agree { border-color:#00830088; color:#006300; }
.capag.differ { border-color:#eda100; background:#fff4d6; color:#6b3a00; }
table.captab { width:100%; border-collapse:collapse; font-size:12.5px; margin:4px 0 8px; }
table.captab th { text-align:left; font-size:11px; color:var(--ink2); font-weight:600; border-bottom:1px solid var(--border); padding:4px 6px; }
table.captab td { border-bottom:1px solid var(--border); padding:4px 6px; vertical-align:top; }
table.captab tr.grp td { background:var(--bg); font-weight:650; font-size:11.5px; color:var(--ink); padding-top:6px; }
table.captab td.num { white-space:nowrap; font-weight:650; }
.capv { display:inline-block; min-width:22px; text-align:center; border-radius:5px; padding:0 5px; }
.capv.same { background:#d9f2d9; color:#005200; }
.capv.off { background:#ffd9a8; color:#6b3a00; outline:1px solid #eda100; }
.capsum { font-weight:650; }
.capsum.differ { color:#a35a00; }
.capsum.agree { color:#007000; }
.vchip { display:inline-block; font-size:11px; border:1px solid #eda10088; color:#8a4a00; border-radius:20px; padding:1px 8px; margin:2px 2px 0 0; }
@media (prefers-color-scheme: dark) { .vchip { color:#eda100; } .vbox.ok { color:#0ca30c; }
  .capag.agree { color:#0ca30c; } .capag.differ { background:#3a2a00; color:#ffd27a; }
  .capv.same { background:#0f3a12; color:#8be08b; } .capv.off { background:#4a3000; color:#ffd27a; }
  .capsum.differ { color:#eda100; } .capsum.agree { color:#0ca30c; } }

.main { display:grid; grid-template-columns:1.15fr .85fr; gap:12px; margin-bottom:12px; }
.map-wrap { position:relative; height:600px; overflow:hidden; }
#map { position:absolute; inset:0; }
#map-fallback { position:absolute; inset:0; display:none; align-items:center; justify-content:center; color:var(--ink2); padding:20px; text-align:center; }
.legend { display:flex; flex-wrap:wrap; gap:4px 14px; padding:8px 12px; margin-bottom:8px; font-size:12.5px; color:var(--ink2); align-items:center; }
.legend .dot { display:inline-block; width:11px; height:11px; border-radius:50%; margin-right:5px; vertical-align:-1px; box-shadow:0 0 0 2px var(--surface); }
.listing { height:600px; overflow-y:auto; padding:8px; }
.fcard { border:1px solid var(--border); border-left-width:5px; border-radius:8px; padding:8px 10px; margin-bottom:8px; cursor:pointer; background:var(--surface); }
.fcard:hover { border-color:var(--accent); }
.fcard .nm { font-weight:650; font-size:13.5px; }
.fcard .meta { color:var(--ink2); font-size:12px; margin:1px 0; }
.chip { display:inline-block; font-size:10.5px; border:1px solid var(--border); border-radius:20px; padding:1px 8px; margin:3px 4px 0 0; color:var(--ink2); background:var(--bg); }
.chip.st-open { color:#006300; border-color:#00830055; }
.chip.st-warn { color:#8a4a00; border-color:#eda10066; }
.chip.study { color:var(--accent); border-color:var(--accent); }
.fcard .mini { font-size:11.5px; color:var(--accent); margin-top:2px; }

.charts { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:12px; }
.chart { padding:12px 14px; }
.chart h3 { margin:0 0 4px; font-size:13.5px; }
.chart .note { color:var(--muted); font-size:11px; margin:0 0 8px; }
.bar-row { display:grid; grid-template-columns:170px 1fr 52px; gap:8px; align-items:center; padding:3px 0; border-radius:5px; }
.bar-row:hover { background:var(--bg); }
.bar-label { font-size:12px; color:var(--ink2); text-align:right; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.bar-track { height:14px; position:relative; }
.bar-fill { position:absolute; left:0; top:0; bottom:0; border-radius:0 4px 4px 0; min-width:2px; }
.bar-val { font-size:12px; font-variant-numeric:tabular-nums; }

.modal-bg { position:fixed; inset:0; background:rgba(0,0,0,.55); display:none; z-index:2000; align-items:flex-start; justify-content:center; overflow-y:auto; padding:30px 14px; }
.modal { max-width:860px; width:100%; padding:18px 20px; position:relative; }
.modal h2 { margin:0 34px 2px 0; font-size:18px; }
.modal .sub { color:var(--ink2); font-size:13px; margin-bottom:10px; }
.modal .x { position:absolute; top:10px; right:12px; font-size:16px; padding:2px 10px; }
.modal img.sat { width:100%; border-radius:8px; border:1px solid var(--border); margin:8px 0; }
.satstats { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin:10px 0; }
.satstats > div { border:1px solid var(--border); border-radius:8px; padding:8px 10px; background:var(--surface); }
.satstats .v { font-size:22px; font-weight:700; font-variant-numeric:tabular-nums; }
.satstats .l { font-size:11.5px; color:var(--ink2); }
.modal table { width:100%; border-collapse:collapse; font-size:12.5px; }
.modal td { border-bottom:1px solid var(--grid); padding:5px 8px; vertical-align:top; }
.modal td:first-child { color:var(--ink2); white-space:nowrap; width:150px; }
.modal .links a { color:var(--accent); margin-right:16px; font-size:13px; }
.tabbar { display:flex; gap:6px; margin:10px 0 0; border-bottom:1px solid var(--grid); }
.tabbar .tab { border:1px solid var(--border); border-bottom:none; border-radius:8px 8px 0 0; background:var(--bg); color:var(--ink2); padding:6px 14px; font-size:12.5px; cursor:pointer; }
.tabbar .tab.active { background:var(--surface); color:var(--ink); font-weight:650; border-color:var(--accent); }
.tabpane { padding-top:10px; }
.tssnote { color:var(--muted); font-size:11.5px; margin:10px 0 0; }
.dom { color:var(--muted); font-size:0.85em; }

/* off-screen (not display:none) so the report's Leaflet map can lay out and load tiles before printing */
#report { position:absolute; left:-10000px; top:0; width:7.5in; height:0; overflow:hidden; background:#fff; color:#111; }
#report .rmap { width:7.2in; max-width:100%; height:5in; border:1px solid #999; border-radius:4px; margin-bottom:6px; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
#report .rpin { width:22px; height:22px; border-radius:50%; border:2px solid #fff; color:#fff; font:700 10px/18px Arial, sans-serif; text-align:center; box-shadow:0 0 0 1px #333; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
#report .rlegend { font-size:8.5pt; color:#333; margin-bottom:4px; }
#report .rlegend span { margin-right:12px; white-space:nowrap; }
#report .rlegend .dot { display:inline-block; width:9px; height:9px; border-radius:50%; margin-right:4px; vertical-align:middle; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
#report .dom { color:#666; font-size:0.85em; }
#report .rcard img.ov { float:none; display:block; max-width:100%; max-height:4.2in; margin:6px 0 2px; }
#report .cap { font-size:8.5pt; color:#444; font-style:italic; }
#report .ovcrop { position:relative; overflow:hidden; max-width:100%; margin:6px 0 2px; border:1px solid #999; border-radius:4px; }
#report .rcard .ovcrop img { position:absolute; max-width:none; max-height:none; height:auto; float:none; margin:0; border:0; border-radius:0; }
@media print {
  body { background:#fff; color:#111; font-size:10.5pt; }
  .app { display:none !important; }
  #report { position:static; left:auto; width:auto; height:auto; overflow:visible; display:block; padding:0; }
  #report h1 { font-size:19pt; margin:0 0 2px; }
  #report .sub { color:#444; margin-bottom:10px; }
  #report h2 { font-size:13pt; border-bottom:2px solid #0f2a4a; color:#0f2a4a; padding-bottom:2px; margin:18px 0 8px; }
  #report table { width:100%; border-collapse:collapse; font-size:8.5pt; margin-bottom:10px; }
  #report th { background:#0f2a4a; color:#fff; padding:4px 6px; text-align:left; font-size:8pt; }
  #report td { border-bottom:1px solid #ccc; padding:3.5px 6px; vertical-align:top; }
  #report tr { page-break-inside:avoid; }
  #report .rcard { border:1px solid #bbb; border-radius:6px; padding:8px 10px; margin-bottom:10px; page-break-inside:avoid; }
  #report .rcard h3 { margin:0 0 3px; font-size:11pt; color:#0f2a4a; }
  #report .rcard .m { color:#444; font-size:9pt; margin-bottom:4px; }
  #report .rcard img { max-width:3.4in; max-height:2.4in; float:right; margin:0 0 6px 10px; border:1px solid #999; border-radius:4px; }
  #report .rcard p { margin:2px 0; font-size:9pt; }
  #report .rcard::after { content:""; display:block; clear:both; }
  #report table.captab { font-size:8.5pt; margin:2px 0 4px; clear:none; }
  #report table.captab th, #report table.captab td { border-bottom:1px solid #ccc; padding:2px 4px; color:#111; }
  #report table.captab tr.grp td { background:#eef1f5; color:#0f2a4a; }
  #report .capag { font-size:9pt; padding:3px 6px; margin:3px 0; background:#f6f6f4; color:#111; border:1px solid #bbb; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  #report .capag.differ { background:#fff4d6; border-color:#eda100; color:#6b3a00; }
  #report .capag.agree { border-color:#008300; color:#006300; }
  #report .capv.same { background:#d9f2d9; color:#005200; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  #report .capv.off { background:#ffd9a8; color:#6b3a00; outline:1px solid #eda100; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  #report .capsum.differ { color:#a35a00; } #report .capsum.agree { color:#007000; }
}
@media (max-width: 1000px) { .main, .charts { grid-template-columns:1fr; } .kpis { grid-template-columns:repeat(2,1fr); } .map-wrap { height:420px; } .listing { height:420px; } }

button:focus-visible, input:focus-visible, a:focus-visible, .chip.toggle input:focus-visible + span { outline:2px solid var(--accent); outline-offset:2px; }

/* ---------- toll + traffic layers ---------- */
.traffic-bar { display:flex; flex-wrap:wrap; align-items:center; gap:16px; padding:10px 12px; margin-bottom:12px; }
.switch-row { display:flex; align-items:center; gap:6px; font-size:13px; cursor:pointer; }
.switch-row input[type=checkbox] { width:16px; height:16px; }
.switch-row.sub-toggle { font-size:12px; color:var(--ink2); }
.toll-legend-mini { font-size:11.5px; color:var(--ink2); }
#traffic-shell { margin-bottom:12px; }
.traffic-controls { padding:10px 12px; margin-bottom:10px; }
.traffic-layer-groups { display:flex; flex-wrap:wrap; gap:18px; margin-bottom:10px; }
.traffic-group { display:flex; flex-direction:column; gap:5px; min-width:190px; }
.traffic-group h4 { margin:0 0 2px; font-size:11px; text-transform:uppercase; letter-spacing:.4px; color:var(--muted); }
.chip.toggle { display:inline-flex; align-items:center; gap:5px; cursor:pointer; width:fit-content; }
.chip.toggle input { margin:0; }
.nodata-tag { color:var(--muted); font-size:10px; margin-left:2px; }
.traffic-selectors { display:flex; flex-wrap:wrap; gap:8px; align-items:center; border-top:1px solid var(--border); padding-top:10px; }
.traffic-kpis { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; margin-bottom:10px; }
.traffic-kpis .kpi .v.na { font-size:14px; color:var(--muted); font-weight:600; }
.traffic-kpis-note { color:var(--muted); font-size:11px; margin:-4px 0 10px; }
#traffic-empty-notices .notice { border:1px solid var(--border); border-left:4px solid var(--muted); border-radius:8px; padding:7px 10px; margin-bottom:6px; font-size:12.5px; background:var(--surface); }
#traffic-empty-notices .notice a { color:var(--accent); margin-left:6px; }
#traffic-legend span.dim { opacity:.42; }
.toll-badge { background:#c94b1f; color:#fff; border-radius:6px; width:22px; height:22px; display:flex; align-items:center; justify-content:center; font-weight:700; font-size:12px; border:2px solid #fff; box-shadow:0 0 0 1px rgba(0,0,0,.3); }
.toll-badge.former { background:transparent; color:var(--ink2); border:2px dashed var(--muted); box-shadow:none; }
.wim-badge { background:#1baf7a; border-radius:5px; width:20px; height:20px; display:flex; align-items:center; justify-content:center; border:2px solid #fff; }
.wim-badge svg { width:13px; height:13px; }
.count-badge { background:#eda100; width:16px; height:16px; border:2px solid #fff; border-radius:3px; }
.count-badge.short { background:transparent; border:2px solid #eda100; }
.sev-badge, .cite-badge { border-radius:50%; color:#fff; font-weight:700; font-size:10px; display:flex; align-items:center; justify-content:center; border:2px solid #fff; }
.sev-badge.fatal { background:#c0392b; width:22px; height:22px; }
.sev-badge.injury { background:#eda100; width:19px; height:19px; }
.sev-badge.pdo { background:#4a3aa7; width:16px; height:16px; }
.cite-badge { background:var(--accent); width:22px; height:22px; }
</style>
</head><body>
<div class="app">
  <header class="topbar">
    <div>
      <h1>WV Truck Parking Dashboard</h1>
      <div class="sub">Semi-truck parking inventory &mdash; I-64 &middot; I-77 (Turnpike) &middot; I-79 &middot; US-19 (Corridor L) &middot; generated __GENDATE__</div>
    </div>
    <div class="actions">
      <label class="switch-row" title="Also export/print toll facility and traffic-data layers (only layers currently visible and populated are included)"><input type="checkbox" id="chk-include-traffic"> <span>Include traffic data</span></label>
      <button id="btn-csv" title="Download the currently filtered facilities as CSV">Export filtered CSV</button>
      <button id="btn-report" class="primary" title="Build a printable report of the current filtered view (print to PDF from the dialog)">Generate report</button>
    </div>
  </header>

  <div class="kpis">
    <div class="kpi card"><div class="v" id="k-shown">&ndash;</div><div class="l">Locations shown</div></div>
    <div class="kpi card"><div class="v" id="k-oper">&ndash;</div><div class="l">Operating w/ designated parking</div></div>
    <div class="kpi card"><div class="v" id="k-spaces">&ndash;</div><div class="l">Est. designated truck spaces</div></div>
    <div class="kpi card"><div class="v" id="k-field">&ndash;</div><div class="l">Field-verified</div></div>
    <div class="kpi card"><div class="v" id="k-corr">&ndash;</div><div class="l">Corridors in view</div></div>
  </div>

  <div class="filters card">
    <input type="text" id="f-search" placeholder="Search name / exit / county / notes&hellip;">
    <div class="dd" data-key="type" data-label="Type"></div>
    <div class="dd" data-key="corr" data-label="Corridor"></div>
    <div class="dd" data-key="own" data-label="Ownership"></div>
    <div class="dd" data-key="status" data-label="Status"></div>
    <div class="dd" data-key="conf" data-label="Confidence"></div>
    <div class="dd" id="dd-hidden" style="display:none"></div>
    <label class="switch-row" title="Limit the map, list, counts, charts, report and CSV export to the Parking Study locations listed in included_locations.txt"><input type="checkbox" id="f-study"> <span>Show Parking Study Locations only</span></label>
    <select id="f-sort"><option value="corr">Sort: corridor order</option><option value="name">Sort: name A&ndash;Z</option><option value="spaces">Sort: est. spaces (high first)</option></select>
    <button id="f-reset">Reset</button>
    <span class="spacer" id="f-count"></span>
  </div>

  <div class="traffic-bar card">
    <label class="switch-row" title="Show/hide the 6 active WV toll facilities"><input type="checkbox" id="sw-toll" checked> <span>Toll facilities</span></label>
    <label class="switch-row sub-toggle" title="Show former toll facilities (currently: Dunbar Toll Bridge, now free) in a separate dashed style"><input type="checkbox" id="sw-toll-former"> <span>Former tolls</span></label>
    <span class="toll-legend-mini" id="toll-legend-mini"></span>
    <label class="switch-row" title="Master switch for all traffic-intelligence layers (AADT, count stations, weigh-in-motion, citations/enforcement, crashes, live conditions)"><input type="checkbox" id="sw-traffic"> <span>Traffic Data</span></label>
  </div>

  <div id="traffic-shell" style="display:none">
    <div class="traffic-controls card" id="traffic-controls">
      <div class="traffic-layer-groups" id="traffic-layer-groups"></div>
      <div class="traffic-selectors" id="traffic-selectors">
        <div class="dd" data-key="year" data-label="Year"></div>
        <div class="dd" data-key="route" data-label="Route"></div>
        <div class="dd" data-key="county" data-label="County"></div>
        <div class="dd" data-key="dir" data-label="Direction"></div>
        <div class="dd" data-key="vclass" data-label="Vehicle class"></div>
        <div class="dd" data-key="pclass" data-label="Passenger/Commercial"></div>
        <div class="dd" data-key="citype" data-label="Citation/offense type"></div>
        <div class="dd" data-key="sev" data-label="Crash severity"></div>
        <div class="dd" data-key="agency" data-label="Enforcement agency"></div>
        <button id="tf-reset" title="Reset traffic filters (does not affect truck-parking filters)">Reset traffic filters</button>
        <button id="tf-methodology" title="Rate-calculation methodology and important definitions">Methodology</button>
      </div>
    </div>
    <div class="traffic-kpis card" id="traffic-kpis"></div>
    <div class="traffic-kpis-note">Tiles read "Not available" (never 0) when the underlying layer has no data, or when a rate's numerator/denominator coverage can't be reliably matched. See Methodology.</div>
    <div id="traffic-empty-notices"></div>
    <div class="legend card" id="traffic-legend"></div>
  </div>

  <div class="legend card" id="legend"></div>

  <div class="main">
    <div class="map-wrap card">
      <div id="map"></div>
      <div id="map-fallback">Map could not load (Leaflet CDN / internet unavailable). Filtering, details, reports and CSV export still work.</div>
    </div>
    <div class="listing card" id="listing"></div>
  </div>

  <div class="charts">
    <div class="chart card">
      <h3>Est. designated truck spaces by corridor</h3>
      <p class="note">Operating public / private / paid-reservable facilities in the current filter; analyst midpoints of published or imagery ranges.</p>
      <div id="chart-corr"></div>
    </div>
    <div class="chart card">
      <h3>Locations by category</h3>
      <p class="note">All locations in the current filter, including informal sites, candidates and resolved non-facilities.</p>
      <div id="chart-class"></div>
    </div>
  </div>

  <div class="sub" style="color:var(--muted);font-size:11.5px;">
    Source: wv-truck-parking-master.csv. Map layers: OpenStreetMap (streets), Esri World Imagery (satellite).
    Click any facility for full details and site satellite imagery. Space totals are estimates; see per-facility confidence.
    Questions or corrections? Contact Mohammad Ahmad at <a href="mailto:mohammad.ahmad@mail.wvu.edu" style="color:var(--accent)">mohammad.ahmad@mail.wvu.edu</a>.
  </div>
</div>

<div class="modal-bg" id="modal-bg">
  <div class="modal card" id="modal"></div>
</div>

<div id="report"></div>

<script>
var DATA = __DATA__;
// PowerShell JSON turns one-element arrays into objects and empty ones into {} -- normalize
DATA.forEach(function (r) { r.caps = Array.isArray(r.caps) ? r.caps : (r.caps && r.caps.group ? [r.caps] : []); });
var COLS = __COLS__;
var TSS_DATE = '__TSSDATE__';

/* ---------- toll + traffic data (tools\traffic-lib.js, inlined at build time) ---------- */
__TRAFFIC_LIB__
var TRAFFIC = __TRAFFIC__;
var TRAFFIC_META = __TRAFFIC_META__;
var CLASS_META = {
  'public':    { label:'Public facility',            light:'#2a78d6', dark:'#3987e5' },
  'private':   { label:'Private truck stop',         light:'#1baf7a', dark:'#199e70' },
  'paid':      { label:'Paid reservable lot',        light:'#eda100', dark:'#c98500' },
  'informal':  { label:'Informal / big-box',         light:'#008300', dark:'#008300' },
  'candidate': { label:'Candidate site (satellite)', light:'#4a3aa7', dark:'#9085e9' },
  'none':      { label:'No capacity / closed / ghost', light:'#898781', dark:'#898781' }
};
var CLASS_ORDER = ['public','private','paid','informal','candidate','none'];
var CORR_ORDER = ['I-64','I-77 (incl. Turnpike)','I-79','US-19 (Corridor L)','US-19 / I-79 junction'];
var isDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
function ccolor(cls) { var m = CLASS_META[cls]; return isDark ? m.dark : m.light; }

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
  });
}
function trunc(s, n) { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
function byId(id) { return document.getElementById(id); }

/* ---------- hidden facilities (viewer-side exclusions, persisted) ---------- */
var hiddenSet = {};
try {
  (JSON.parse(localStorage.getItem('wvtp-hidden') || '[]')).forEach(function (n) {
    if (DATA.some(function (r) { return r.name === n; })) { hiddenSet[n] = true; }
  });
} catch (e) {}
function saveHidden() {
  try { localStorage.setItem('wvtp-hidden', JSON.stringify(Object.keys(hiddenSet))); } catch (e) {}
}
function hiddenCount() { return Object.keys(hiddenSet).length; }
function toggleHidden(id) {
  var n = DATA[id].name;
  if (hiddenSet[n]) { delete hiddenSet[n]; } else { hiddenSet[n] = true; }
  saveHidden(); render();
}
var hiddenNamesCache = [];
function unhideAt(i) {
  delete hiddenSet[hiddenNamesCache[i]];
  saveHidden(); render();
}
function unhideAll() { hiddenSet = {}; saveHidden(); render(); }
function toggleHiddenDd() {
  var dd = byId('dd-hidden');
  var wasOpen = dd.classList.contains('open');
  closeAllDropdowns();
  if (!wasOpen) { dd.classList.add('open'); }
}
function renderHiddenDd() {
  var dd = byId('dd-hidden');
  hiddenNamesCache = Object.keys(hiddenSet).sort();
  if (!hiddenNamesCache.length) {
    dd.style.display = 'none'; dd.classList.remove('open'); dd.innerHTML = '';
    return;
  }
  var h = '<button type="button" title="Facilities you have hidden from the dashboard" onclick="event.stopPropagation();toggleHiddenDd()"><span class="t">Hidden</span><span class="n">' + hiddenNamesCache.length + '</span> &#9662;</button>';
  h += '<div class="dd-panel" onclick="event.stopPropagation()"><span class="dd-clear" onclick="unhideAll()">Unhide all</span>';
  hiddenNamesCache.forEach(function (n, i) {
    h += '<div class="hrow"><span>' + esc(n) + '</span><a href="#" onclick="unhideAt(' + i + ');return false;">Unhide</a></div>';
  });
  h += '</div>';
  dd.innerHTML = h;
  dd.style.display = '';
}

/* ---------- filters (multi-select checkbox dropdowns) ---------- */
var FACETS = [
  { key: 'type', label: 'Type' },
  { key: 'corr', label: 'Corridor' },
  { key: 'own', label: 'Ownership' },
  { key: 'status', label: 'Status' },
  { key: 'conf', label: 'Confidence' }
];
var filterState = {};
FACETS.forEach(function (f) { filterState[f.key] = {}; });
function facetActive(key) {
  return Object.keys(filterState[key]).filter(function (v) { return filterState[key][v]; });
}
function updateDdBadge(dd) {
  var n = facetActive(dd.getAttribute('data-key')).length;
  var b = dd.querySelector('button .n');
  b.style.display = n ? '' : 'none';
  b.textContent = n;
}
function closeAllDropdowns() {
  Array.prototype.slice.call(document.querySelectorAll('.filters .dd.open')).forEach(function (d) { d.classList.remove('open'); });
}
document.addEventListener('click', closeAllDropdowns);
(function buildDropdowns() {
  Array.prototype.slice.call(document.querySelectorAll('.filters .dd[data-key]')).forEach(function (dd) {
    var key = dd.getAttribute('data-key'), label = dd.getAttribute('data-label');
    var seen = {};
    DATA.forEach(function (r) { seen[r[key]] = true; });
    var vals = Object.keys(seen).sort();
    var h = '<button type="button" title="Select one or more ' + esc(label.toLowerCase()) + ' values"><span class="t">' + esc(label) + '</span><span class="n" style="display:none">0</span> &#9662;</button>';
    h += '<div class="dd-panel"><span class="dd-clear">Clear selection</span>';
    vals.forEach(function (v) {
      h += '<label><input type="checkbox" value="' + esc(v) + '"> <span>' + esc(v) + '</span></label>';
    });
    h += '</div>';
    dd.innerHTML = h;
    dd.querySelector('button').addEventListener('click', function (e) {
      e.stopPropagation();
      var wasOpen = dd.classList.contains('open');
      closeAllDropdowns();
      if (!wasOpen) { dd.classList.add('open'); }
    });
    dd.querySelector('.dd-panel').addEventListener('click', function (e) { e.stopPropagation(); });
    dd.querySelector('.dd-clear').addEventListener('click', function () {
      filterState[key] = {};
      Array.prototype.slice.call(dd.querySelectorAll('input')).forEach(function (cb) { cb.checked = false; });
      updateDdBadge(dd); render();
    });
    Array.prototype.slice.call(dd.querySelectorAll('input')).forEach(function (cb) {
      cb.addEventListener('change', function () {
        filterState[key][cb.value] = cb.checked;
        updateDdBadge(dd); render();
      });
    });
  });
})();

function filtered() {
  var q = byId('f-search').value.toLowerCase();
  var studyOnly = byId('f-study').checked;
  return DATA.filter(function (r) {
    if (hiddenSet[r.name]) return false;
    if (studyOnly && !r.studyId) return false;
    for (var i = 0; i < FACETS.length; i++) {
      var act = facetActive(FACETS[i].key);
      if (act.length && act.indexOf(r[FACETS[i].key]) === -1) return false;
    }
    if (q) {
      var hay = (r.name + ' ' + r.raw['Milepost / exit'] + ' ' + r.raw['County'] + ' ' + r.raw['Notes'] + ' ' + r.raw['Facility type']).toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  });
}
function sorted(rows) {
  var mode = byId('f-sort').value;
  rows = rows.slice();
  if (mode === 'name') { rows.sort(function (a, b) { return a.name.localeCompare(b.name); }); }
  else if (mode === 'spaces') { rows.sort(function (a, b) { return (b.capMid || 0) - (a.capMid || 0); }); }
  else { rows.sort(function (a, b) { return a.id - b.id; }); }
  return rows;
}

/* ---------- legend ---------- */
(function () {
  var h = '<b style="color:var(--ink)">Map legend:</b>';
  CLASS_ORDER.forEach(function (c) {
    h += '<span><span class="dot" style="background:' + ccolor(c) + '"></span>' + esc(CLASS_META[c].label) + '</span>';
  });
  byId('legend').innerHTML = h;
})();

/* ---------- map ---------- */
var map = null, markerLayer = null;
var STREETS_URL = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}';
var STREETS_ATTR = 'Tiles &copy; Esri &mdash; Esri, HERE, Garmin, USGS, &copy; OpenStreetMap contributors';
if (window.L) {
  map = L.map('map').setView([38.7, -81.1], 7);
  // Esri street basemap: OSM's volunteer tile servers block pages opened from
  // file:// (no Referer header), which is how this dashboard is usually viewed.
  var streets = L.tileLayer(STREETS_URL, { maxZoom: 19, attribution: STREETS_ATTR });
  var satTiles = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { maxZoom: 19, attribution: 'Esri World Imagery' });
  streets.addTo(map);
  L.control.layers({ 'Streets': streets, 'Satellite': satTiles }, null, { collapsed: false, position: 'topright' }).addTo(map);
  markerLayer = L.layerGroup().addTo(map);
  var FitCtl = L.Control.extend({
    options: { position: 'topleft' },
    onAdd: function () {
      var d = L.DomUtil.create('div', 'leaflet-bar');
      d.innerHTML = '<a href="#" title="Zoom to filtered results" style="font-size:11px;width:auto;padding:0 8px;">Fit results</a>';
      d.onclick = function (e) { e.preventDefault(); fitToResults(); return false; };
      return d;
    }
  });
  map.addControl(new FitCtl());
} else {
  byId('map-fallback').style.display = 'flex';
}
function fitToResults() {
  if (!map) return;
  var pts = filtered().filter(function (r) { return r.lat != null; }).map(function (r) { return [r.lat, r.lon]; });
  if (pts.length) { map.fitBounds(pts, { padding: [30, 30], maxZoom: 13 }); }
}
function popupHtml(r) {
  return '<div style="min-width:220px"><b>' + esc(r.name) + '</b><br>' +
    esc(r.type) + ' &middot; ' + esc(r.own) + '<br>' +
    '<b>Spaces:</b> ' + capSummaryHtml(r) + '<br>' +
    '<b>Status:</b> ' + esc(r.status) + ' &middot; ' + esc(r.conf) + '<br>' +
    '<a href="#" onclick="openDetail(' + r.id + ');return false;">Full details + satellite</a> &middot; ' +
    '<a href="#" onclick="toggleHidden(' + r.id + ');return false;" title="Exclude this facility from the map, list, counts and exports (undo via the Hidden control)">Hide</a></div>';
}
function renderMarkers(rows) {
  if (!markerLayer) return;
  markerLayer.clearLayers();
  rows.forEach(function (r) {
    if (r.lat == null) return;
    L.circleMarker([r.lat, r.lon], {
      radius: 8, color: isDark ? '#1a1a19' : '#ffffff', weight: 2,
      fillColor: ccolor(r.capClass), fillOpacity: 0.95
    }).bindPopup(popupHtml(r)).addTo(markerLayer);
  });
}

/* ---------- list ---------- */
function statusChipClass(st) {
  if (st.indexOf('Open') === 0) return 'chip st-open';
  if (st === 'Under construction' || st === 'Unverified') return 'chip st-warn';
  return 'chip';
}
function renderList(rows) {
  var h = '';
  rows.forEach(function (r) {
    h += '<div class="fcard" style="border-left-color:' + ccolor(r.capClass) + '" onclick="openDetail(' + r.id + ')">' +
      '<span class="hidebtn" onclick="event.stopPropagation();toggleHidden(' + r.id + ')" title="Hide this facility from the map, list, counts and exports (undo via the Hidden control in the filter bar)">&times; Hide</span>' +
      '<div class="nm">' + esc(r.name) + '</div>' +
      '<div class="meta">' + esc(r.corr) + ' &middot; ' + esc(trunc(r.raw['Milepost / exit'], 42)) + ' &middot; ' + esc(r.raw['County']) + ' Co.</div>' +
      '<div class="meta"><b>Spaces:</b> ' + capSummaryHtml(r) + (r.capMid != null ? ' &middot; study est. ~' + r.capMid : '') + '</div>' +
      '<span class="' + statusChipClass(r.status) + '">' + esc(r.status) + '</span>' +
      '<span class="chip">' + esc(r.type) + '</span>' +
      '<span class="chip">' + esc(r.conf) + '</span>' +
      (r.studyId ? '<span class="chip study" title="Parking Study location ID (included_locations.txt)">Study ' + esc(r.studyId) + '</span>' : '') +
      (r.satc && r.satc.total_spots !== '' ? '<span class="chip" title="Satellite count on the ' + esc(r.satc.image_date) + ' image: total spots / occupied / empty (open the facility for method and caveats)">Sat ' + esc(r.satc.total_spots) + ' spots &middot; ' + esc(r.satc.occupied_at_image) + ' occ &middot; ' + esc(r.satc.empty_at_image) + ' empty</span>' : '') +
      (r.lat != null && map ? '<div class="mini" onclick="event.stopPropagation();zoomTo(' + r.id + ')">Show on map &rarr;</div>' : '<div class="mini" style="color:var(--muted)">no coordinates</div>') +
      '</div>';
  });
  byId('listing').innerHTML = h || '<div style="padding:16px;color:var(--ink2)">No facilities match the current filters.</div>';
}
function zoomTo(id) {
  var r = DATA[id];
  if (!map || r.lat == null) return;
  map.setView([r.lat, r.lon], 15);
  markerLayer.eachLayer(function (m) {
    var ll = m.getLatLng();
    if (Math.abs(ll.lat - r.lat) < 1e-9 && Math.abs(ll.lng - r.lon) < 1e-9) { m.openPopup(); }
  });
}

/* ---------- KPIs ---------- */
function isOperating(r) { return r.capClass === 'public' || r.capClass === 'private' || r.capClass === 'paid'; }
function spacesSum(rows) {
  var s = 0, unk = 0;
  rows.forEach(function (r) {
    if (isOperating(r)) { if (r.capMid != null) { s += r.capMid; } else { unk++; } }
  });
  return { sum: s, unk: unk };
}
function renderKpis(rows) {
  var sp = spacesSum(rows);
  byId('k-shown').textContent = rows.length + ' / ' + DATA.length;
  byId('k-oper').textContent = rows.filter(isOperating).length;
  byId('k-spaces').textContent = '~' + sp.sum + (sp.unk ? '+' : '');
  byId('k-field').textContent = rows.filter(function (r) { return r.conf === 'Field-verified'; }).length;
  byId('k-corr').textContent = CORR_ORDER.filter(function (c) { return rows.some(function (r) { return r.corr === c; }); }).length;
  byId('f-count').textContent = 'Showing ' + rows.length + ' of ' + DATA.length + ' locations' + (hiddenCount() ? ' (' + hiddenCount() + ' hidden)' : '');
}

/* ---------- charts ---------- */
function barChart(el, items) {
  var max = 0;
  items.forEach(function (it) { if (it.value > max) { max = it.value; } });
  var h = '';
  items.forEach(function (it) {
