    rows.forEach(function (r) { if (r.corr === c && isOperating(r) && r.capMid != null) { s += r.capMid; } });
    if (rows.some(function (r) { return r.corr === c; })) { corrItems.push({ label: c, value: s, color: 'var(--accent)' }); }
  });
  barChart(byId('chart-corr'), corrItems);
  var clsItems = [];
  CLASS_ORDER.forEach(function (c) {
